import { BLUE, RED, type Simulation } from "./simulation";

export interface Summary {
  tone: "start" | "wave" | "calm" | "fade" | "empty" | "meadow";
  headline: string;
  lines: string[];
  chips: { label: string; value: string }[];
}

export interface Turn {
  i: number;
  t: number;
  v: number;
  peak: boolean;
