export function vigor(p: Params, b: Blob): number {
  const full = 0.5 * (b.kind === BLUE ? p.blueCopyAt : p.redCopyAt);
  return VIGOR_FLOOR + (1 - VIGOR_FLOOR) * Math.min(1, Math.max(0, b.energy / full));
}

