    const out = dx * nx + dz * nz;
    if (out > 0) {
      const tx = dx - out * nx;
      const tz = dz - out * nz;
      const tl = Math.hypot(tx, tz) || 1;
      const mag = Math.hypot(dx, dz);
      dx = (tx / tl) * mag;
      dz = (tz / tl) * mag;
