private assignShelter(): void {
  for (const b of this.blueList) b.sheltered = false;
  const near = this.shelterScratch;
  for (const t of this.trees) {
    near.length = 0;
    this.blueGrid.forEachNear(t.x, t.z, SHELTER_RADIUS, (b, d2) => {
