}

interface Pulse {
  mesh: THREE.Mesh<THREE.RingGeometry, THREE.MeshBasicMaterial>;
  life: number;
  max: number;
  size: number;
}

export interface SceneHooks {
  onPick: (id: number | null) => void;
}

export interface FrameInput {
  sim: Simulation;
