    this.bodies = new Instances(this.scene, makeBodyGeometry(), bodyMat, 512, { cast: true }, true);
    this.eyes = new Instances(this.scene, new THREE.SphereGeometry(1, 14, 10), eyeMat, 1024);
    this.glints = new Instances(this.scene, new THREE.SphereGeometry(1, 8, 6), glintMat, 1024);
    this.cheeks = new Instances(this.scene, new THREE.SphereGeometry(1, 12, 8), cheekMat, 1024, {}, true);
    this.mouths = new Instances(
      this.scene,
      new THREE.TorusGeometry(0.05, 0.013, 6, 16, Math.PI).rotateZ(Math.PI),
