import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import { RoomEnvironment } from "three/examples/jsm/environments/RoomEnvironment.js";
import {
  BLUE,
  FLEE_FRACTION,
  MAX_SLOTS,
  SLOT_EAT,
  SLOT_GROW,
  SLOT_RIPE,
  SLOT_WAIT,
  blobCopyAt,
  blobMaxSpeed,
  blobVision,
  slotAngle,
  type Action,
  type Blob,
  type Kind,
  type SimEvent,
  type Simulation,
  type Tree,
} from "../sim/simulation";
import { BODY_H, SPRITE, makeBodyGeometry, makeGrassTexture, makeSpriteAtlas, surfaceFrame } from "./shapes";

const COLORS = {
  blue: new THREE.Color("#3f88ff"),
  red: new THREE.Color("#ff5263"),
  bluePale: new THREE.Color("#b9c6de"),
  redPale: new THREE.Color("#dcb7bc"),
  blueGlow: new THREE.Color("#a8d4ff"),
  redGlow: new THREE.Color("#ffc2a8"),
  cheekBlue: new THREE.Color("#ff9fc0"),
  cheekRed: new THREE.Color("#ffd0d6"),
  fruitRipe: new THREE.Color("#b5f23a"),
  fruitYoung: new THREE.Color("#5e9e3a"),
  fruitBud: new THREE.Color("#7fb55a"),
};

const CANOPY_TINTS = ["#3c9d5d", "#2f8f55", "#47a865", "#3a9470", "#4aa35a"].map((c) => new THREE.Color(c));
const CANOPY_Y = 1.75;
const CANOPY_RX = 1.18;
const CANOPY_RY = 0.86;

interface Visual {
  heading: number;
  hop: number;
  hopAmp: number;
  brow: number;
  eyeWide: number;
  blinkAt: number;
  blinkT: number;
  lastX: number;
  lastZ: number;
  lastAction: Action;
  x: number;
  y: number;
  z: number;
  scale: number;
  seen: number;
}

interface Ghost {
  x: number;
  z: number;
  heading: number;
  kind: Kind;
  t0: number;
  type: "fade" | "poof";
  scale: number;
}

interface Particle {
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  life: number;
  max: number;
