const problems: string[] = [];
const check = (ok: boolean, msg: string) => {
  console.log(`${ok ? "✓" : "✗"} ${msg}`);
  if (!ok) problems.push(msg);
};

async function blobScreenPos(page: Page, kind: number) {
  return page.evaluate((kind) => {
    const e = (window as any).__garden;
    const s = e.scene;
    const cam = s.camera;
    const rect = s.renderer.domElement.getBoundingClientRect();
    const mul = (m: any, v: number[]) => {
      const el = m.elements;
      return [0, 1, 2, 3].map((r) => el[r] * v[0] + el[4 + r] * v[1] + el[8 + r] * v[2] + el[12 + r] * v[3]);
    };
    const candidates = e.sim.blobs
      .filter((b: any) => b.kind === kind && b.alive)
      .map((b: any) => {
        const c = mul(cam.projectionMatrix, mul(cam.matrixWorldInverse, [b.x, 0.4, b.z, 1]));
        return {
          id: b.id,
          x: rect.left + ((c[0] / c[3] + 1) / 2) * rect.width,
