import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import { RoomEnvironment } from "three/examples/jsm/environments/RoomEnvironment.js";
import {
  BLUE,
  FLEE_FRACTION,
  MAX_SLOTS,
  SLOT_EAT,
  SLOT_GROW,
  SLOT_RIPE,
  SLOT_WAIT,
  blobCopyAt,
  blobMaxSpeed,
  blobVision,
  slotAngle,
  type Action,
  type Blob,
